{"content":"/* The most-ordered drinks board, shared by the landing page and the
   participant quick-picks. There is deliberately no fetching here: the
   pages call `/api/leaderboard` themselves and hand the payload over, so
   every function below stays pure enough to drive without a browser.

   Counting matches app/leaderboard.py — by base drink name, not exact
   configuration — so `normalize` must stay in sync with the Python
   `normalize_drink` (lowercase, collapse whitespace, trim). */

(function (root) {
  'use strict';

  var DEFAULT_EMPTY_TEXT = 'No group orders yet. Once a few drinks are in, '
    + 'the five most-ordered show up here.';

  function normalize(value) {
    return String(value || '').toLowerCase().replace(/\s+/g, ' ').trim();
  }

  function plural(count, one, many) {
    return count + ' ' + (count === 1 ? one : many);
  }

  /* Find the menu item for a leaderboard row, or null when this store
     does not serve it. Quick-picks only offer matches, so a tap can never
     lead somewhere the menu cannot complete. */
  function matchMenuItem(menuItems, drinkName) {
    var want = normalize(drinkName);
    if (!want || !Array.isArray(menuItems)) return null;
    for (var index = 0; index < menuItems.length; index += 1) {
      var item = menuItems[index];
      if (item && normalize(item.name) === want) return item;
    }
    return null;
  }

  /* The actionable subset of a board: entries this menu can serve, each
     paired with its item, capped at `limit`. */
  function quickPicks(entries, menuItems, limit) {
    var picks = [];
    var seen = {};
    var max = Math.max(1, Math.min(10, limit || 5));
    (entries || []).forEach(function (entry) {
      if (picks.length >= max || !entry) return;
      var item = matchMenuItem(menuItems, entry.drink);
      if (!item || seen[normalize(item.name)]) return;
      seen[normalize(item.name)] = true;
      picks.push({ drink: item.name, drinks: entry.drinks, orders: entry.orders, item: item });
    });
    return picks;
  }

  function node(doc, tag, className, text) {
    var element = doc.createElement(tag);
    if (className) element.className = className;
    if (text !== undefined && text !== null) element.textContent = text;
    return element;
  }

  function countText(entry) {
    return '×' + entry.drinks;
  }

  function describeEntry(entry) {
    return entry.drink + ', ordered ' + plural(entry.drinks, 'cup', 'cups')
      + ' in ' + plural(entry.orders || 0, 'order', 'orders');
  }

  /* Render the informational board into an <ol>: ranked rows with cup
     counts, or a single muted row while there is nothing to rank. */
  function renderBoard(doc, list, board, options) {
    var entries = (board && board.entries) || [];
    var emptyText = (options && options.emptyText) || DEFAULT_EMPTY_TEXT;
    list.textContent = '';
    if (!entries.length) {
      list.append(node(doc, 'li', 'muted', emptyText));
      return entries;
    }
    entries.forEach(function (entry, index) {
      var row = node(doc, 'li', null, null);
      row.setAttribute('aria-label', 'Number ' + (index + 1) + ': ' + describeEntry(entry));
      row.append(node(doc, 'span', 'leaderboard-rank', String(index + 1)));
      row.append(node(doc, 'span', 'leaderboard-name', entry.drink));
      row.append(node(doc, 'strong', 'leaderboard-count', countText(entry)));
      list.append(row);
    });
    return entries;
  }

  /* Render one-tap chips into the participant picker. The panel stays
     hidden when nothing on the board matches this store's menu, so the
     order form never advertises a dead end. */
  function renderQuickPicks(doc, panel, list, picks, onPick) {
    list.textContent = '';
    if (!picks || !picks.length) {
      panel.hidden = true;
      return [];
    }
    picks.forEach(function (pick) {
      var chip = node(doc, 'button', 'popular-chip', null);
      chip.type = 'button';
      chip.setAttribute('aria-label', 'Choose ' + describeEntry(pick));
      chip.append(node(doc, 'span', null, pick.drink));
      chip.append(node(doc, 'strong', null, countText(pick)));
      chip.addEventListener('click', function () { onPick(pick.item); });
      list.append(chip);
    });
    panel.hidden = false;
    return picks;
  }

  root.BobaLeaderboard = {
    normalize: normalize,
    matchMenuItem: matchMenuItem,
    quickPicks: quickPicks,
    renderBoard: renderBoard,
    renderQuickPicks: renderQuickPicks,
  };
})(typeof window !== 'undefined' ? window : this);
